          <label for="project-name">Project name</label>
          <div class="form-row">
            <input id="project-name" name="name" type="text" autocomplete="off">
            <button type="submit">Create project</button>
          </div>
        </form>
        <div id="projects" class="projects"></div>
      </section>
      <section id="project-detail" hidden>
        <button id="back" type="button">Projects</button>
        <h2 id="project-title"></h2>
        <form id="create-task">
          <label for="task-title">Task title</label>
          <div class="form-row">
            <input id="task-title" name="title" type="text" autocomplete="off">
            <button type="submit">Create task</button>
          </div>
        </form>
        <label for="task-filter">Task filter</label>
        <select id="task-filter">
          <option>All</option>
          <option>Open</option>
          <option>Completed</option>
        </select>
        <div id="tasks" class="projects"></div>
      </section>
      <p id="error" role="alert" hidden></p>
    </main>
  </body>
</html>
:root { color-scheme: light; font-family: system-ui, sans-serif; color: #172033; background: #f5f7fb; }
body { margin: 0; }
.container { max-width: 760px; margin: 4rem auto; padding: 2rem; background: white; border-radius: 12px; box-shadow: 0 8px 30px #17203312; }
